const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    `Expected exactly one analytics report, received ${items.length}`
  );
}

const report = items[0].json;
const payload = report.payload;

if (!payload || typeof payload !== 'object') {
  throw new Error('Report payload is missing or invalid');
}

const requiredSections = [
  'scope',
  'orders',
  'revenue',
  'metadata',
  'products',
  'geography',
  'time_series',
];

for (const section of requiredSections) {
  if (!payload[section] || typeof payload[section] !== 'object') {
    throw new Error(`Missing or invalid payload section: ${section}`);
  }
}

const requiredArrays = [
  ['products', 'top_10_by_revenue'],
  ['products', 'top_10_by_quantity'],
  ['geography', 'top_10_countries'],
  ['time_series', 'monthly_metrics'],
  ['time_series', 'daily_metrics'],
];

for (const [section, field] of requiredArrays) {
  if (!Array.isArray(payload[section][field])) {
    throw new Error(`Expected ${section}.${field} to be an array`);
  }
}

// JSONB values may be numeric strings.
// Validate them without modifying the original payload.
const numericFields = [
  ['orders', 'gross_revenue'],
  ['orders', 'cancellation_rate_pct'],
  ['orders', 'average_order_value'],
  ['orders', 'completed_orders'],
  ['orders', 'cancelled_orders'],
  ['revenue', 'gross_revenue'],
  ['revenue', 'net_revenue'],
  ['revenue', 'cancellation_value'],
];

for (const [section, field] of numericFields) {
  const value = payload[section][field];

  if (value === null || value === undefined || !Number.isFinite(Number(value))) {
    throw new Error(`Invalid numeric value: ${section}.${field}`);
  }
}

const period = payload.metadata.period;

if (!period?.start || !period?.end) {
  throw new Error('Business reporting period is missing');
}

return [{
  json: {
    ...report,
    report_validation: {
      valid: true,
      validated_at: new Date().toISOString(),
      sections_found: requiredSections,
      monthly_records: payload.time_series.monthly_metrics.length,
      daily_records: payload.time_series.daily_metrics.length,
      business_period: {
        start: period.start,
        end: period.end,
      },
    },
  },
}];

const items = $input.all();

if (items.length !== 1) {
  throw new Error(`Expected one report, received ${items.length}`);
}

const report = items[0].json;
const payload = report.payload;

function toNumber(value, field) {
  if (value === null || value === undefined || value === '') {
    throw new Error(`Missing numeric value: ${field}`);
  }

  const number = Number(value);

  if (!Number.isFinite(number)) {
    throw new Error(`Invalid numeric value: ${field}`);
  }

  return number;
}

function normalizeRows(rows, fields, section) {
  return rows.map((row, index) => {
    const normalized = { ...row };

    for (const field of fields) {
      if (normalized[field] !== null && normalized[field] !== undefined) {
        normalized[field] = toNumber(
          normalized[field],
          `${section}[${index}].${field}`
        );
      }
    }

    return normalized;
  });
}

// Reporting period: use business dates from metadata, not outer
// PostgreSQL timestamp fields that may have serialization shifts.
const periodStart = payload.metadata.period.start.slice(0, 10);
const periodEnd = payload.metadata.period.end.slice(0, 10);

const endDate = new Date(`${periodEnd}T00:00:00Z`);
const lastDayOfEndMonth = new Date(
  Date.UTC(
    endDate.getUTCFullYear(),
    endDate.getUTCMonth() + 1,
    0
  )
).getUTCDate();

const isFinalMonthPartial =
  endDate.getUTCDate() < lastDayOfEndMonth;

// Normalize monthly metrics and identify the partial final month.
const monthlyMetrics = normalizeRows(
  payload.time_series.monthly_metrics,
  [
    'units_sold',
    'net_revenue',
    'gross_revenue',
    'completed_orders',
    'cancellation_value',
    'revenue_growth_pct',
  ],
  'monthly_metrics'
).map((month) => {
  const monthKey = month.sales_month.slice(0, 7);
  const endMonthKey = periodEnd.slice(0, 7);

  const isPartial =
    monthKey === endMonthKey && isFinalMonthPartial;

  return {
    ...month,
    is_partial_period: isPartial,

    // Do not compare a partial month directly with a full month.
    comparable_revenue_growth_pct: isPartial
      ? null
      : month.revenue_growth_pct,
  };
});

const dailyMetrics = normalizeRows(
  payload.time_series.daily_metrics,
  ['gross_revenue', 'completed_orders', 'cancellation_value'],
  'daily_metrics'
);

const topProductsByRevenue = normalizeRows(
  payload.products.top_10_by_revenue,
  ['units_sold', 'gross_revenue'],
  'top_10_by_revenue'
);

const topProductsByQuantity = normalizeRows(
  payload.products.top_10_by_quantity,
  ['units_sold', 'gross_revenue'],
  'top_10_by_quantity'
);

const topCountries = normalizeRows(
  payload.geography.top_10_countries,
  [
    'units_sold',
    'net_revenue',
    'gross_revenue',
    'completed_orders',
    'cancellation_value',
    'average_order_value',
    'sales_transaction_lines',
  ],
  'top_10_countries'
);

const preparedData = {
  report: {
    id: report.report_id,
    generated_at: report.generated_at,
    project: payload.metadata.project,
    source_dataset: payload.metadata.source_dataset,
    dataset_scope: report.dataset_scope,
    currency: report.currency,
    period: {
      start: periodStart,
      end: periodEnd,
    },
  },

  scope: {
    completed_batches: toNumber(
      payload.scope.completed_batches,
      'scope.completed_batches'
    ),
    total_transactions: toNumber(
      payload.scope.total_transactions,
      'scope.total_transactions'
    ),
    cancellation_records: toNumber(
      payload.scope.cancellation_records,
      'scope.cancellation_records'
    ),
  },

  orders: {
    gross_revenue: toNumber(payload.orders.gross_revenue, 'orders.gross_revenue'),
    total_invoices: toNumber(payload.orders.total_invoices, 'orders.total_invoices'),
    cancelled_orders: toNumber(payload.orders.cancelled_orders, 'orders.cancelled_orders'),
    completed_orders: toNumber(payload.orders.completed_orders, 'orders.completed_orders'),
    total_items_sold: toNumber(payload.orders.total_items_sold, 'orders.total_items_sold'),
    cancellation_value: toNumber(payload.orders.cancellation_value, 'orders.cancellation_value'),
    average_order_value: toNumber(payload.orders.average_order_value, 'orders.average_order_value'),
    cancellation_rate_pct: toNumber(payload.orders.cancellation_rate_pct, 'orders.cancellation_rate_pct'),
    average_items_per_order: toNumber(payload.orders.average_items_per_order, 'orders.average_items_per_order'),
  },

  revenue: {
    gross_revenue: toNumber(payload.revenue.gross_revenue, 'revenue.gross_revenue'),
    net_revenue: toNumber(payload.revenue.net_revenue, 'revenue.net_revenue'),
    cancellation_value: toNumber(payload.revenue.cancellation_value, 'revenue.cancellation_value'),
    sales_transaction_lines: toNumber(payload.revenue.sales_transaction_lines, 'revenue.sales_transaction_lines'),
    total_transaction_lines: toNumber(payload.revenue.total_transaction_lines, 'revenue.total_transaction_lines'),
  },

  products: {
    overall_metrics: {
      total_units_sold: toNumber(
        payload.products.overall_metrics.total_units_sold,
        'products.total_units_sold'
      ),
      cancellation_units: toNumber(
        payload.products.overall_metrics.cancellation_units,
        'products.cancellation_units'
      ),
      distinct_products_sold: toNumber(
        payload.products.overall_metrics.distinct_products_sold,
        'products.distinct_products_sold'
      ),
    },
    top_10_by_revenue: topProductsByRevenue,
    top_10_by_quantity: topProductsByQuantity,
  },

  geography: {
    total_countries: toNumber(
      payload.geography.total_countries,
      'geography.total_countries'
    ),
    total_gross_revenue: toNumber(
      payload.geography.total_gross_revenue,
      'geography.total_gross_revenue'
    ),
    total_completed_orders: toNumber(
      payload.geography.total_completed_orders,
      'geography.total_completed_orders'
    ),
    top_10_countries: topCountries,
  },

  time_series: {
    daily_metrics: dailyMetrics,
    monthly_metrics: monthlyMetrics,
  },

  data_quality: {
    monthly_records: monthlyMetrics.length,
    daily_active_dates: dailyMetrics.length,
    final_month_is_partial: isFinalMonthPartial,
    partial_month: isFinalMonthPartial ? periodEnd.slice(0, 7) : null,
  },
};

return [{
  json: {
    report_data: preparedData,

    // Retain the original source payload for auditability.
    source_payload: payload,

    report_validation: report.report_validation,
  },
}];

const items = $input.all();

if (items.length !== 1) {
  throw new Error(`Expected one prepared report, received ${items.length}`);
}

const input = items[0].json;
const report = input.report_data;

if (!report?.orders || !report?.scope || !report?.products?.overall_metrics) {
  throw new Error('Required order metrics are missing from report_data');
}

const orders = report.orders;
const scope = report.scope;
const products = report.products.overall_metrics;

const totalInvoices = orders.total_invoices;
const completedOrders = orders.completed_orders;
const cancelledOrders = orders.cancelled_orders;

if (totalInvoices <= 0) {
  throw new Error('Total invoices must be greater than zero');
}

// Calculate rates from the underlying counts.
// These calculations also let us cross-check stored percentages.
const completionRate = (completedOrders / totalInvoices) * 100;
const cancellationRate = (cancelledOrders / totalInvoices) * 100;

const calculatedCancellationRate = Number(
  cancellationRate.toFixed(2)
);

const storedCancellationRate = orders.cancellation_rate_pct;

// Generate deterministic business observations.
const findings = [
  {
    type: 'positive',
    title: 'Strong order completion rate',
    description:
      `${completedOrders.toLocaleString('en-GB')} of ` +
      `${totalInvoices.toLocaleString('en-GB')} invoices were completed, ` +
      `representing a ${completionRate.toFixed(2)}% completion rate.`
  },
  {
    type: calculatedCancellationRate >= 5 ? 'warning' : 'neutral',
    title: 'Order cancellation rate',
    description:
      `${cancelledOrders.toLocaleString('en-GB')} orders were cancelled, ` +
      `representing ${calculatedCancellationRate.toFixed(2)}% of all invoices.`
  },
  {
    type: 'neutral',
    title: 'Average order value',
    description:
      `The average order value was ${report.report.currency} ` +
      `${orders.average_order_value.toFixed(2)}.`
  },
  {
    type: 'neutral',
    title: 'Average basket size',
    description:
      `Each completed order contained approximately ` +
      `${orders.average_items_per_order.toFixed(2)} items on average.`
  },
  {
    type: 'info',
    title: 'Cancellation records versus cancelled orders',
    description:
      `The dataset contains ${scope.cancellation_records.toLocaleString('en-GB')} ` +
      `cancellation records and ${cancelledOrders.toLocaleString('en-GB')} ` +
      `cancelled orders. These are separate measures.`
  }
];

const ordersInsights = {
  summary: {
    total_invoices: totalInvoices,
    completed_orders: completedOrders,
    cancelled_orders: cancelledOrders,
    completion_rate_pct: Number(completionRate.toFixed(2)),
    cancellation_rate_pct: calculatedCancellationRate,
    stored_cancellation_rate_pct: storedCancellationRate,
    average_order_value: orders.average_order_value,
    average_items_per_order: orders.average_items_per_order,
    total_items_sold: orders.total_items_sold,
    cancellation_records: scope.cancellation_records,
    cancellation_units: products.cancellation_units
  },

  findings,

  validation: {
    completion_and_cancellation_counts_match:
      completedOrders + cancelledOrders === totalInvoices,

    cancellation_rate_matches_stored:
      calculatedCancellationRate === Number(storedCancellationRate.toFixed(2))
  }
};

return [{
  json: {
    ...input,
    orders_insights: ordersInsights
  }
}];

const items = $input.all();

if (items.length !== 1) {
  throw new Error(`Expected one report, received ${items.length}`);
}

const input = items[0].json;
const report = input.report_data;

if (!report?.revenue) {
  throw new Error('Revenue metrics are missing from report_data');
}

const revenue = report.revenue;

const grossRevenue = revenue.gross_revenue;
const netRevenue = revenue.net_revenue;
const cancellationValue = revenue.cancellation_value;

const salesLines = revenue.sales_transaction_lines;
const totalLines = revenue.total_transaction_lines;

if (grossRevenue <= 0) {
  throw new Error('Gross revenue must be greater than zero');
}

if (totalLines <= 0) {
  throw new Error('Total transaction lines must be greater than zero');
}

// Calculate revenue performance indicators.
const revenueLostPct =
  (cancellationValue / grossRevenue) * 100;

const revenueRetainedPct =
  (netRevenue / grossRevenue) * 100;

const salesLineRatioPct =
  (salesLines / totalLines) * 100;

// Calculate expected net revenue independently.
const calculatedNetRevenue =
  grossRevenue - cancellationValue;

// Currency rounding for reconciliation.
const roundCurrency = (value) =>
  Number(value.toFixed(2));

const roundedGrossRevenue = roundCurrency(grossRevenue);
const roundedNetRevenue = roundCurrency(netRevenue);
const roundedCancellationValue = roundCurrency(cancellationValue);
const roundedCalculatedNetRevenue = roundCurrency(calculatedNetRevenue);

// Generate deterministic business observations.
const findings = [
  {
    type: 'positive',
    title: 'Net revenue generated',
    description:
      `The business generated ${report.report.currency} ` +
      `${netRevenue.toLocaleString('en-GB', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      })} in net revenue after accounting for cancellations.`
  },
  {
    type: 'info',
    title: 'Revenue impact of cancellations',
    description:
      `${report.report.currency} ` +
      `${cancellationValue.toLocaleString('en-GB', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      })} in revenue was associated with cancelled transactions, ` +
      `representing ${revenueLostPct.toFixed(2)}% of gross revenue.`
  },
  {
    type: 'positive',
    title: 'Revenue retention',
    description:
      `${revenueRetainedPct.toFixed(2)}% of gross revenue was retained ` +
      `as net revenue after cancellations.`
  },
  {
    type: 'neutral',
    title: 'Sales transaction activity',
    description:
      `${salesLines.toLocaleString('en-GB')} of ` +
      `${totalLines.toLocaleString('en-GB')} transaction lines ` +
      `were classified as sales lines, representing ` +
      `${salesLineRatioPct.toFixed(2)}% of all transaction lines.`
  }
];

const revenueInsights = {
  summary: {
    gross_revenue: roundedGrossRevenue,
    cancellation_value: roundedCancellationValue,
    net_revenue: roundedNetRevenue,
    revenue_lost_pct: Number(revenueLostPct.toFixed(2)),
    revenue_retained_pct: Number(revenueRetainedPct.toFixed(2)),
    sales_transaction_lines: salesLines,
    total_transaction_lines: totalLines,
    sales_line_ratio_pct: Number(salesLineRatioPct.toFixed(2))
  },

  findings,

  validation: {
    revenue_reconciles:
      roundedCalculatedNetRevenue === roundedNetRevenue,

    transaction_lines_reconcile:
      salesLines <= totalLines,

    revenue_percentages_reconcile:
      Number(
        (revenueLostPct + revenueRetainedPct).toFixed(2)
      ) === 100
  }
};

return [{
  json: {
    ...input,
    revenue_insights: revenueInsights
  }
}];

const items = $input.all();

if (items.length !== 1) {
  throw new Error(`Expected one report, received ${items.length}`);
}

const input = items[0].json;
const report = input.report_data;

if (!report?.products || !report?.geography) {
  throw new Error('Product or geography data is missing');
}

const products = report.products;
const geography = report.geography;

const revenueRankings = products.top_10_by_revenue;
const quantityRankings = products.top_10_by_quantity;
const countries = geography.top_10_countries;

if (
  !Array.isArray(revenueRankings) ||
  !Array.isArray(quantityRankings) ||
  !Array.isArray(countries) ||
  revenueRankings.length === 0 ||
  quantityRankings.length === 0 ||
  countries.length === 0
) {
  throw new Error('One or more ranking arrays are empty or invalid');
}

// Helpers
const round = (value) => Number(value.toFixed(2));

const percentage = (part, total) => {
  if (total <= 0) return 0;
  return round((part / total) * 100);
};

const currency = report.report.currency;

const formatCurrency = (value) =>
  `${currency} ${value.toLocaleString('en-GB', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  })}`;

const productName = (product) =>
  product.description ??
  product.product_name ??
  product.stock_code ??
  'Unknown product';

// Product analysis
const topProductByRevenue = revenueRankings[0];
const topProductByQuantity = quantityRankings[0];

const top10ProductRevenue = revenueRankings.reduce(
  (total, product) => total + product.gross_revenue,
  0
);

const top10ProductUnits = quantityRankings.reduce(
  (total, product) => total + product.units_sold,
  0
);

const totalGrossRevenue = report.revenue.gross_revenue;
const totalUnitsSold = products.overall_metrics.total_units_sold;

const top10RevenueContributionPct = percentage(
  top10ProductRevenue,
  totalGrossRevenue
);

const top10QuantityContributionPct = percentage(
  top10ProductUnits,
  totalUnitsSold
);

const sameLeadingProduct =
  String(topProductByRevenue.stock_code) ===
  String(topProductByQuantity.stock_code);

// Geography analysis
const topCountryByNetRevenue = [...countries].sort(
  (a, b) => b.net_revenue - a.net_revenue
)[0];

const topCountryByGrossRevenue = [...countries].sort(
  (a, b) => b.gross_revenue - a.gross_revenue
)[0];

const top10CountryGrossRevenue = countries.reduce(
  (total, country) => total + country.gross_revenue,
  0
);

const top10CountryNetRevenue = countries.reduce(
  (total, country) => total + country.net_revenue,
  0
);

const totalNetRevenue = report.revenue.net_revenue;

const top10CountryGrossContributionPct = percentage(
  top10CountryGrossRevenue,
  totalGrossRevenue
);

const top10CountryNetContributionPct = percentage(
  top10CountryNetRevenue,
  totalNetRevenue
);

// Identify the UK without assuming its position in the array.
const uk = countries.find(
  (country) =>
    String(country.country).trim().toLowerCase() ===
    'united kingdom'
);

const ukGrossRevenueSharePct = uk
  ? percentage(uk.gross_revenue, totalGrossRevenue)
  : null;

const ukNetRevenueSharePct = uk
  ? percentage(uk.net_revenue, totalNetRevenue)
  : null;

// Build product ranking output.
const topProductsByRevenue = revenueRankings.map((product) => ({
  stock_code: product.stock_code,
  product_name: productName(product),
  units_sold: product.units_sold,
  gross_revenue: round(product.gross_revenue),
  revenue_contribution_pct: percentage(
    product.gross_revenue,
    totalGrossRevenue
  )
}));

const topProductsByQuantity = quantityRankings.map((product) => ({
  stock_code: product.stock_code,
  product_name: productName(product),
  units_sold: product.units_sold,
  gross_revenue: round(product.gross_revenue)
}));

// Build geography ranking output.
const topCountries = [...countries]
  .sort((a, b) => b.net_revenue - a.net_revenue)
  .map((country) => ({
    country: country.country,
    gross_revenue: round(country.gross_revenue),
    net_revenue: round(country.net_revenue),
    completed_orders: country.completed_orders,
    revenue_contribution_pct: percentage(
      country.net_revenue,
      totalNetRevenue
    )
  }));

// Deterministic business findings.
const findings = [
  {
    type: 'positive',
    title: 'Leading product by revenue',
    description:
      `${productName(topProductByRevenue)} ` +
      `(stock code ${topProductByRevenue.stock_code}) generated ` +
      `${formatCurrency(topProductByRevenue.gross_revenue)} in gross revenue.`
  },
  {
    type: 'info',
    title: 'Leading product by quantity',
    description:
      `${productName(topProductByQuantity)} ` +
      `(stock code ${topProductByQuantity.stock_code}) led sales volume ` +
      `with ${topProductByQuantity.units_sold.toLocaleString('en-GB')} units sold.`
  },
  {
    type: 'neutral',
    title: 'Top 10 product revenue contribution',
    description:
      `The top 10 products by revenue generated ` +
      `${formatCurrency(top10ProductRevenue)}, accounting for ` +
      `${top10RevenueContributionPct}% of total gross revenue.`
  },
  {
    type: 'positive',
    title: 'Leading geographical market',
    description:
      `${topCountryByNetRevenue.country} generated the highest net revenue ` +
      `among the countries in the top 10 ranking, at ` +
      `${formatCurrency(topCountryByNetRevenue.net_revenue)}.`
  },
  {
    type: 'info',
    title: 'UK revenue contribution',
    description: uk
      ? `The United Kingdom generated ${formatCurrency(uk.net_revenue)} ` +
        `in net revenue, representing ${ukNetRevenueSharePct}% of total net revenue.`
      : 'The United Kingdom was not found in the top 10 country results.'
  },
  {
    type: 'neutral',
    title: 'Geographical revenue concentration',
    description:
      `The top 10 countries generated ` +
      `${formatCurrency(top10CountryNetRevenue)} in combined net revenue, ` +
      `representing ${top10CountryNetContributionPct}% of total net revenue.`
  }
];

const productGeographyInsights = {
  products: {
    summary: {
      distinct_products_sold: products.overall_metrics.distinct_products_sold,
      total_units_sold: totalUnitsSold,
      cancellation_units: products.overall_metrics.cancellation_units,
      top_product_by_revenue: topProductsByRevenue[0],
      top_product_by_quantity: topProductsByQuantity[0],
      same_leading_product: sameLeadingProduct,
      top_10_gross_revenue: round(top10ProductRevenue),
      top_10_revenue_contribution_pct: top10RevenueContributionPct,
      top_10_units_sold: top10ProductUnits,
      top_10_quantity_contribution_pct: top10QuantityContributionPct
    },
    top_10_by_revenue: topProductsByRevenue,
    top_10_by_quantity: topProductsByQuantity
  },

  geography: {
    summary: {
      total_countries: geography.total_countries,
      top_country_by_net_revenue: topCountryByNetRevenue.country,
      top_country_by_gross_revenue: topCountryByGrossRevenue.country,
      top_10_gross_revenue: round(top10CountryGrossRevenue),
      top_10_net_revenue: round(top10CountryNetRevenue),
      top_10_gross_contribution_pct:
        top10CountryGrossContributionPct,
      top_10_net_contribution_pct:
        top10CountryNetContributionPct,
      uk: uk
        ? {
            gross_revenue: round(uk.gross_revenue),
            net_revenue: round(uk.net_revenue),
            gross_revenue_share_pct: ukGrossRevenueSharePct,
            net_revenue_share_pct: ukNetRevenueSharePct
          }
        : null
    },
    top_10_countries: topCountries
  },

  findings
};

const validation = {
  // Product ranking checks
  product_revenue_leader_matches_ranking:
    topProductByRevenue.stock_code === revenueRankings[0].stock_code,

  product_quantity_leader_matches_ranking:
    topProductByQuantity.stock_code === quantityRankings[0].stock_code,

  // Product aggregation checks
  top_10_product_revenue_not_exceeding_total:
    top10ProductRevenue <= totalGrossRevenue + 0.01,

  top_10_product_units_not_exceeding_total:
    top10ProductUnits <= totalUnitsSold,

  // Geography aggregation checks
  top_10_country_gross_revenue_not_exceeding_total:
    top10CountryGrossRevenue <= totalGrossRevenue + 0.01,

  top_10_country_net_revenue_not_exceeding_total:
    top10CountryNetRevenue <= totalNetRevenue + 0.01
};

return [{
  json: {
    ...input,
    product_geography_insights: {
