const escapeHtml = (value) => {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
};

const isMissing = (value) =>
  value === null ||
  value === undefined ||
  value === '';

const number = (value, decimals = 0) => {
  if (isMissing(value)) return 'N/A';

  const numericValue = Number(value);

  if (!Number.isFinite(numericValue)) return 'N/A';

  return numericValue.toLocaleString('en-GB', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals
  });
};

const money = (value) => {
  if (isMissing(value)) return 'N/A';

  const numericValue = Number(value);

  if (!Number.isFinite(numericValue)) return 'N/A';

  return new Intl.NumberFormat('en-GB', {
    style: 'currency',
    currency,
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(numericValue);
};

const percentage = (value) => {
  if (isMissing(value)) return 'N/A';

  const numericValue = Number(value);

  if (!Number.isFinite(numericValue)) return 'N/A';

  return `${number(numericValue, 2)}%`;
};

const formatDate = (value) => {
  if (isMissing(value)) return 'N/A';

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return String(value);
  }

  return date.toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    timeZone: 'UTC'
  });
};

const formatDateTime = (value) => {
  if (isMissing(value)) return 'N/A';

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return String(value);
  }

  return date.toLocaleString('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'UTC'
  });
};

const formatKey = (key) =>
  String(key)
    .replace(/_/g, ' ')
    .replace(/\b\w/g, (char) => char.toUpperCase());

const currencyKeys = [
  'gross_revenue',
  'net_revenue',
  'cancellation_value',
  'average_order_value',
  'total_gross_revenue',
  'average_gross_revenue_per_active_date',
  'top_10_gross_revenue',
  'top_10_net_revenue'
];

const decimalKeys = [
  'average_items_per_order',
  'average_completed_orders_per_active_date'
];

const formatSummaryValue = (key, value) => {
  if (isMissing(value)) return 'N/A';

  if (currencyKeys.includes(key)) {
    return money(value);
  }

  if (key.endsWith('_pct')) {
    return percentage(value);
  }

  if (decimalKeys.includes(key)) {
    return number(value, 2);
  }

  if (typeof value === 'boolean') {
    return value ? 'Yes' : 'No';
  }

  if (typeof value === 'number') {
    return number(value);
  }

  return String(value);
};

