const items = $input.all();

// Retrieve the original analytics report.
const reportPackage = $('Assemble Report Sections')
  .first()
  .json
  .report_package;

const reportId = Number(reportPackage?.metadata?.report_id);

if (!Number.isSafeInteger(reportId) || reportId <= 0) {
  throw new Error('Invalid or missing analytics report ID');
}

const output = [];

for (let index = 0; index < items.length; index++) {
  const item = items[index];

  // Get the actual saved PDF path.
  const storagePath = item.json?.fileName;

  if (!storagePath || typeof storagePath !== 'string') {
    throw new Error(`Missing PDF storage path at item ${index}`);
  }

  // Validate PDF binary.
  if (!item.binary?.pdf) {
    throw new Error(`Missing PDF binary at item ${index}`);
  }

  // Read actual binary contents to get exact size in bytes.
  const pdfBuffer = await this.helpers.getBinaryDataBuffer(
    index,
    'pdf'
  );

  // Retrieve and validate SHA-256 checksum.
  const checksum = item.json?.checksum_sha256;

  if (
    typeof checksum !== 'string' ||
    !/^[a-f0-9]{64}$/i.test(checksum)
  ) {
    throw new Error(`Invalid SHA-256 checksum at item ${index}`);
  }

  const contentType = item.binary.pdf.mimeType;

  if (contentType !== 'application/pdf') {
    throw new Error(`Unexpected content type at item ${index}`);
  }

  output.push({
    json: {
      report_id: reportId,

      filename: storagePath.split(/[\\/]/).pop(),

      storage_path: storagePath,

      content_type: contentType,

      file_size_bytes: pdfBuffer.length,

      checksum_sha256: checksum.toLowerCase()
    },

    pairedItem: {
      item: index
    }
  });
}

return output;
